(function(){
  'use strict';
  const api = window.CORE10_PAPEROPS;
  const el = id => document.getElementById(id);
  let logoData = '';
  const fields = ['industry','form','lang','scope','group','business','site','header','title','color','rows'];
  function updateForms(){
    const old = el('form').value;
    const forms = api.availableForms(el('industry').value);
    el('form').replaceChildren();
    for (const f of forms) {
      const opt = document.createElement('option');
      opt.value = f.id;
      opt.textContent = f.title[el('lang').value] + ' · ' + f.id + (f.status === 'hypothesis' ? ' · প্রস্তাবিত' : '');
      el('form').append(opt);
    }
    if(forms.some(x=>x.id===old)) el('form').value=old;
  }
  function job(){
    const id = el('form').value;
    const brand = {headerName:el('header').value.trim(),color:el('color').value,logo:logoData,
      formTitles:el('title').value.trim() ? {[id]:el('title').value.trim()} : {}};
    return {
      industry:el('industry').value, lang:el('lang').value, scope:el('scope').value,
      groupName:el('group').value.trim(), businessName:el('business').value.trim(),
      siteName:el('site').value.trim(), tableRows:Number(el('rows').value),
      businessBrand:el('scope').value==='business' ? brand : {},
      siteBrand:el('scope').value==='site' ? brand : {}
    };
  }
  function preview(){
    try {
      el('paper').innerHTML = api.renderPrintMarkup(el('form').value,job());
      el('printButton').disabled=false;
      el('status').textContent='প্রিভিউ প্রস্তুত। এখন প্রিন্ট বা PDF করা যাবে।';
    } catch(err) {
      el('printButton').disabled=true;
      el('status').textContent='ফর্ম তৈরি হয়নি: '+err.message;
    }
  }
  el('industry').addEventListener('change',function(){updateForms();el('printButton').disabled=true;});
  el('lang').addEventListener('change',updateForms);
  el('previewButton').addEventListener('click',preview);
  el('printButton').addEventListener('click',function(){if(!this.disabled)window.print();});
  el('logo').addEventListener('change',function(){
    const file=this.files&&this.files[0]; if(!file){logoData='';return;}
    if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000){
      logoData='';this.value='';el('status').textContent='লোগোটি PNG/JPEG/WebP এবং ৫০০ KB-এর মধ্যে হতে হবে।';return;
    }
    const reader=new FileReader();
    reader.onload=()=>{logoData=String(reader.result||'');el('status').textContent='লোগো প্রস্তুত; প্রিভিউ আবার তৈরি করুন।';};
    reader.onerror=()=>{logoData='';el('status').textContent='লোগো পড়া যায়নি।';};
    reader.readAsDataURL(file);
  });
  el('saveButton').addEventListener('click',function(){
    const data={version:1,formId:el('form').value,settings:job()};
    const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download='core10-paperops-settings.json';a.click();
    URL.revokeObjectURL(url);
    el('status').textContent='সেটিংস ফাইল তৈরি হয়েছে; এতে ব্যবসা ও শাখার নাম থাকতে পারে। নিরাপদে রাখুন।';
  });
  el('load').addEventListener('change',function(){
    const file=this.files&&this.files[0];if(!file)return;
    if(file.size>1000000){el('status').textContent='সেটিংস ফাইল ১ MB-এর বেশি হতে পারবে না।';return;}
    const reader=new FileReader();
    reader.onload=function(){
      try{
        const data=JSON.parse(String(reader.result));
        if(data.version!==1||!data.settings||typeof data.settings!=='object')throw Error('INVALID_SETTINGS');
        const s=data.settings;
        if(!api.INDUSTRIES.includes(s.industry)||!['business','site'].includes(s.scope))throw Error('INVALID_SETTINGS');
        for(const key of ['industry','lang','scope']) if(typeof s[key]==='string')el(key).value=s[key];
        for(const [key,property] of [['group','groupName'],['business','businessName'],['site','siteName']])
          el(key).value=typeof s[property]==='string'?s[property].slice(0,120):'';
        el('rows').value=[5,8,12,18].includes(s.tableRows)?String(s.tableRows):'8';
        updateForms();
        if(api.availableForms(s.industry).some(f=>f.id===data.formId))el('form').value=data.formId;
        const b=s.scope==='site'?s.siteBrand:s.businessBrand;
        const v=b&&typeof b==='object'?b:{};
        el('header').value=typeof v.headerName==='string'?v.headerName.slice(0,120):'';
        el('title').value=v.formTitles&&typeof v.formTitles[el('form').value]==='string'?v.formTitles[el('form').value].slice(0,140):'';
        el('color').value=/^#[0-9a-fA-F]{6}$/.test(v.color||'')?v.color:'#174c4c';
        logoData=typeof v.logo==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(v.logo)&&v.logo.length<750000?v.logo:'';
        el('status').textContent='সেটিংস ফিরেছে। প্রিভিউ তৈরি করে যাচাই করুন।';
        el('printButton').disabled=true;
      }catch(err){el('status').textContent='অবৈধ সেটিংস ফাইল: '+err.message;}
    };
    reader.readAsText(file);
    this.value='';
  });
  updateForms();
  preview();
})();

(function(){
'use strict';
const api=window.CORE10_PAPER_KIT, el=id=>document.getElementById(id);
let events=[], businessLogo='', kitBatches=[],kitSettings=null;
const today=new Date();
el('day').value=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
function updateEventOptions(){
  const prev=el('eventType').value;
  const industry=el('industry').value,cls=window.CORE10_PAPEROPS.industryClass(industry);
  el('eventType').replaceChildren();
  for(const [id,d] of Object.entries(api.EVENT_TYPES)){
    if(d.industries&&!d.industries.includes(industry)&&!d.industries.includes(cls))continue;
    const option=document.createElement('option');option.value=id;
    option.textContent=d.name_bn;el('eventType').append(option);
  }
  if([...el('eventType').options].some(x=>x.value===prev))el('eventType').value=prev;
}
el('industry').addEventListener('change',function(){
  events=[];drawEvents();updateEventOptions();el('print').disabled=true;
  el('status').textContent='নতুন ব্যবসার ধরন বেছে নেওয়া হয়েছে; আগের ঘটনার তালিকা রিসেট হয়েছে।';
});
for(const b of api.INDEPENDENT_BOOKS){
  const li=document.createElement('li');
  li.textContent=b.name_bn+(b.status==='POLICY_REQUIRED'
    ?' — অনুমোদিত স্থানীয় আইন/কমপ্লায়েন্স নিয়ম প্রয়োজন'
    :' — প্রিন্টযোগ্য খসড়া পাওয়া যায়, কিন্তু হিসাব/নিয়ন্ত্রণ যাচাই বাকি');
  el('books').append(li);
}
function readSites(){
  const lines=el('sites').value.split(/\r?\n/).filter(x=>x.trim()), out=[], brands={};
  for(const line of lines){
    const p=line.split('|').map(s=>s.trim());
    if(p.length>5)throw Error('INVALID_SITE_LINE');
    const id=p[0],name=p[1];
    if(!id||!name)throw Error('SITE_ID_AND_NAME_REQUIRED');
    out.push({id,name,kind:p[2]||'showroom'});
    const b={};
    if(p[3])b.headerName=p[3];
    if(p[4])b.color=p[4];
    brands[id]=b;
  }
  return {sites:out,brands};
}
function syncSites(){
  try{
    const {sites}=readSites(),old=el('eventSite').value;
    el('eventSite').replaceChildren();
    for(const s of sites){
      const option=document.createElement('option');option.value=s.id;option.textContent=s.name;el('eventSite').append(option);
    }
    if(sites.some(s=>s.id===old))el('eventSite').value=old;
  }catch(e){el('status').textContent=e.message;}
}
function drawEvents(){
  el('eventList').replaceChildren();
  for(let i=0;i<events.length;i++){
    const e=events[i],row=document.createElement('div');row.className='event-row';
    const span=document.createElement('span');
    span.textContent=api.EVENT_TYPES[e.type].name_bn+' · '+e.siteId+' · '+e.eventId;
    const button=document.createElement('button');button.type='button';button.className='remove';
    button.textContent='বাদ';button.addEventListener('click',()=>{events.splice(i,1);drawEvents();el('print').disabled=true;});
    row.append(span,button);el('eventList').append(row);
  }
}
el('sites').addEventListener('change',syncSites);
el('addEvent').addEventListener('click',function(){
  try{
    const type=el('eventType').value,siteId=el('eventSite').value,eventId=el('eventRef').value.trim();
    if(!type||!siteId||!eventId)throw Error('ঘটনার ধরন, শাখা ও রেফারেন্স নম্বর আবশ্যক');
    if(events.some(e=>e.type===type&&e.siteId===siteId&&e.eventId===eventId))throw Error('একই ঘটনা আগে যোগ করা হয়েছে');
    events.push({type,siteId,eventId});drawEvents();el('eventRef').value='';el('print').disabled=true;
    el('status').textContent='ঘটনা যুক্ত হয়েছে। প্রিন্ট সেট পুনরায় তৈরি করুন।';
  }catch(err){el('status').textContent=err.message;}
});
el('logo').addEventListener('change',function(){
  const file=this.files&&this.files[0]; if(!file){businessLogo='';return;}
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000){
    businessLogo='';this.value='';el('status').textContent='অবৈধ লোগো। সর্বোচ্চ ৫০০ KB PNG/JPEG/WebP ব্যবহার করুন।';return;
  }
  const reader=new FileReader();
  reader.onload=()=>{businessLogo=String(reader.result||'');el('print').disabled=true;el('status').textContent='লোগো লোড হয়েছে; আবার কিট তৈরি করুন।';};
  reader.readAsDataURL(file);
});
function previewBatch(){
  if(!kitBatches.length||!kitSettings)throw Error('KIT_NOT_PREPARED');
  const selected=Number(el('batch').value);
  if(!Number.isInteger(selected)||selected<0||selected>=kitBatches.length)throw Error('INVALID_BATCH_SELECTION');
  const pack=kitBatches[selected];
  el('output').innerHTML=api.printKit(pack,kitSettings);
  el('print').disabled=false;
  el('status').textContent='ব্যাচ '+pack.batchNumber+'/'+kitBatches.length+
    ' · '+pack.count+'টি শিট প্রিন্টের জন্য প্রস্তুত। পরের ব্যাচ আলাদা নির্বাচন করুন; কোনো ERP ডাটা পরিবর্তিত হয়নি।';
}
el('batch').addEventListener('change',function(){try{previewBatch();}catch(err){el('print').disabled=true;el('status').textContent=err.message;}});
el('generate').addEventListener('click',function(){
  try{
    const {sites,brands}=readSites();
    const plan=api.planDay({date:el('day').value,industry:el('industry').value,businessName:el('business').value,
      sites,events});
    kitBatches=api.partitionKit(plan,100);
    if(!kitBatches.length)throw Error('EMPTY_PLAN_REQUIRES_OPERATIONAL_EVENT');
    kitSettings={
      groupName:el('group').value,lang:el('lang').value,tableRows:8,
      businessBrand:{color:el('color').value,logo:businessLogo},
      siteBrands:brands
    };
    el('batch').replaceChildren();
    for(const pack of kitBatches){
      const option=document.createElement('option');
      option.value=String(pack.batchNumber-1);
      option.textContent='ব্যাচ '+pack.batchNumber+'/'+kitBatches.length+' · শিট '+pack.firstSheet+'–'+pack.lastSheet;
      el('batch').append(option);
    }
    el('batch').disabled=false;
    el('summary').textContent='প্রস্তুত: '+plan.count+'টি খসড়া শিট ('+plan.dailyCount+'টি শোরুম ক্লোজিং + '+plan.eventCount+'টি ঘটনার)। মোট '+kitBatches.length+'টি আলাদা প্রিন্ট ব্যাচ; কোনো শিট বাদ দেওয়া হয়নি। '+plan.excludedDailySites.length+'টি non-retail সাইটে অপ্রয়োজনীয় sales close বাদ। অসম্পূর্ণ রেজিস্টারগুলো আলাদাভাবে রাখতে হবে।';
    previewBatch();
  }catch(err){kitBatches=[];kitSettings=null;el('batch').disabled=true;el('print').disabled=true;el('status').textContent='কিট তৈরি হয়নি: '+err.message;}
});
el('print').addEventListener('click',function(){if(!this.disabled)window.print();});
updateEventOptions();
syncSites();
})();

(function(){
  'use strict';
  const api=window.CORE10_PAPER_WORKBENCH, el=id=>document.getElementById(id);
  const fields=el('workFields'),flow=el('flow');
  for(const entry of api.FLOWS){
    const option=document.createElement('option');option.value=entry.id;
    option.textContent=entry.bn+' · '+entry.source;
    flow.append(option);
  }
  function render(){
    fields.replaceChildren();
    const schema=api.FLOWS.find(f=>f.id===flow.value), lang=el('lang').value;
    el('source').textContent='Original evidence: '+schema.source;
    for(const f of schema.fields){
      const label=document.createElement('label');
      label.textContent=(lang==='en'?f.en:f.bn)+(f.type==='money'?' (৳)':'');
      let input;
      if(f.type==='bool'){
        input=document.createElement('select');
        for(const [value,name] of [['','— / Unknown'],['yes',lang==='en'?'Yes':'হ্যাঁ'],['no',lang==='en'?'No':'না']]){
          const option=document.createElement('option');option.value=value;option.textContent=name;input.append(option);
        }
      }else{
        input=document.createElement('input');
        input.type=f.type==='money'||f.type==='qty'?'text':'text';
        input.inputMode=f.type==='money'||f.type==='qty'?'decimal':'text';
        input.autocomplete='off';input.maxLength=f.type==='text'?120:35;
        input.placeholder=f.type==='money'?'0.00':f.type==='qty'?'0.0000':'';
      }
      input.dataset.key=f.key;input.dataset.kind=f.type;
      label.append(input);fields.append(label);
    }
    resetResult();
  }
  function resetResult(){
    el('state').textContent='তথ্য দিয়ে যাচাই করুন।';
    el('state').className='status';
    el('blocks').replaceChildren();
    el('entered').replaceChildren();
    el('details').textContent='—';
    el('print').disabled=true;
    el('message').textContent='';
  }
  function gather(){
    const out={};
    for(const input of fields.querySelectorAll('[data-key]')){
      const key=input.dataset.key,kind=input.dataset.kind,val=input.value.trim();
      if(kind==='bool'){if(val!=='')out[key]=val==='yes';}
      else if(val!=='')out[key]=val;
    }
    return out;
  }
  el('check').addEventListener('click',function(){
    resetResult();
    try{
      const inputs=gather(),x=api.evaluate(flow.value,inputs),r=x.result;
      const schema=api.FLOWS.find(z=>z.id===flow.value);
      for(const field of schema.fields){
        if(!Object.prototype.hasOwnProperty.call(inputs,field.key))continue;
        const label=document.createElement('dt'),value=document.createElement('dd');
        label.textContent=(el('lang').value==='en'?field.en:field.bn);
        value.textContent=field.type==='bool'?(inputs[field.key]?'হ্যাঁ / Yes':'না / No'):String(inputs[field.key]);
        el('entered').append(label,value);
      }
      const blocked=r.status==='BLOCK';
      el('state').className='status '+(blocked?'block':'review');
      el('state').textContent=blocked
        ?'BLOCK — গরমিল বা প্রমাণের ঘাটতি; কাজ আটকে যাচাই করুন।'
        :'CHECKS SATISFIED (DRAFT) — স্বতন্ত্র অনুমোদন ও আসল কাগজ যাচাই বাকি।';
      const list=document.createElement('ul');
      for(const code of r.blockers){
        const li=document.createElement('li');li.textContent=code.replaceAll('_',' ');list.append(li);
      }
      if(!r.blockers.length){const p=document.createElement('p');p.textContent='এই পরীক্ষার সীমার মধ্যে কোনো blocker শনাক্ত হয়নি।';el('blocks').append(p);}
      else el('blocks').append(list);
      el('details').textContent=JSON.stringify({source:x.source,control:x.flowId,
        amounts:r.evidence,status:r.status,authorized:false,fieldParityConfirmed:false},null,2);
      el('print').disabled=false;
    }catch(err){
      el('state').textContent='BLOCK — '+err.message;
      el('state').className='status block';
      el('message').textContent='ঘর যাচাই করুন; ভুল বা খালি সংখ্যার জন্য স্বয়ংক্রিয় অনুমোদন দেওয়া হয়নি।';
    }
  });
  el('clear').addEventListener('click',render);
  el('print').addEventListener('click',function(){if(!this.disabled)window.print();});
  flow.addEventListener('change',render);
  el('lang').addEventListener('change',render);
  render();
})();

/* CORE-10 PaperOps: offline, print-only foundation. No credentials, network, or ERP writes.
   Each template is a proposal until the legacy field-by-field control audit is signed off. */
(function(root, factory) {
  'use strict';
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  if (root) root.CORE10_PAPEROPS = api;
})(typeof globalThis === 'object' ? globalThis : this, function() {
  'use strict';
  const t = (bn, en) => ({ bn, en });
  const f = (key, bn, en, industries) => ({ key, label: t(bn, en), industries: industries || ['all'] });
  const s = (bn, en, fields, table) => ({ title: t(bn, en), fields: fields || [], table: table || null });
  const table = (bn, en, cols, rows = 7) => ({ title: t(bn, en), cols: cols.map(c => t(c[0], c[1])), rows });
  const TEMPLATES = [
    {
      id: 'OPS-DAILY', industries: ['all'], cadence: 'daily', status: 'draft', legacyRefs: ['R-01'],
      title: t('দৈনিক শাখা ক্লোজিং ও বিক্রি-স্টক সারাংশ', 'Daily Site Closing & Sales–Stock Summary'),
      rule: t('সাধারণ দিনের একটি সারাংশ। ক্যাশ হস্তান্তর, স্টক স্থানান্তর, বড় ব্যয় বা অনুমোদন প্রয়োজন হলে পৃথক প্রমাণপত্র লাগবে।', 'One routine daily summary. Cash custody, stock transfer, material expenses and exceptions still require separate evidence.'),
      sections: [
        s('দিন ও দায়িত্ব', 'Shift and responsibility', [
          f('date', 'তারিখ', 'Date'), f('shift', 'শিফট', 'Shift'),
          f('prepared', 'প্রস্তুতকারী', 'Prepared by'), f('opening_ref', 'প্রারম্ভিক স্টক / পূর্বদিনের ক্লোজিং নং', 'Opening / previous closing reference'),
          f('hygiene', 'খোলার সময়: পরিচ্ছন্নতা / নিরাপত্তা যাচাই এবং সমস্যা নং', 'Opening hygiene / safety check and exception ref'),
          f('coldchain', 'ফ্রিজ / চিলার অবস্থা ও তাপমাত্রা (সমস্যা হলে নথি)', 'Fridge / chiller condition and temperature (record exceptions)', ['sweets']),
          f('expiry', 'মেয়াদোত্তীর্ণ / অনিরাপদ পণ্য আলাদা করা হয়েছে কি?', 'Expired / unsafe goods segregated?', ['sweets'])
        ]),
        s('পণ্যভিত্তিক মিল', 'Item-level reconciliation', [], table('পণ্য / ইউনিট / খোলা / প্রাপ্তি / বিক্রি / ফেরত / অপচয় / বন্ধ', 'Item / unit / open / received / sold / returned / waste / close', [
          ['পণ্য / কোড', 'Item / code'], ['একক', 'Unit'], ['খোলা', 'Open'], ['প্রাপ্তি', 'Received'], ['বিক্রি', 'Sold'], ['ফেরত', 'Returned'], ['অপচয়', 'Waste'], ['বন্ধ', 'Close']
        ], 9)),
